<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/customer_superapp_v1200.php';$tid=sk1200_tid();$s=sk1200_settings();$expired=0;$cleaned=0;try{if(sk1200_table('customer_intent_matches_v1200')){$q=db()->prepare("UPDATE customer_intent_matches_v1200 m JOIN customer_intents_v1200 i ON i.id=m.intent_id SET m.status='expired',m.updated_at=NOW() WHERE m.tenant_id=? AND m.status='matched' AND i.created_at<DATE_SUB(NOW(),INTERVAL ? HOUR)");$q->execute([$tid,(int)$s['offer_expiry_hours']]);$expired=$q->rowCount();}if(sk1200_table('customer_intents_v1200')){$days=(int)$s['privacy_days'];$q=db()->prepare("DELETE FROM customer_intents_v1200 WHERE tenant_id=? AND status IN ('closed','cancelled') AND created_at<DATE_SUB(NOW(),INTERVAL ? DAY)");$q->execute([$tid,$days]);$cleaned=$q->rowCount();}}catch(Throwable $e){fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}echo json_encode(['ok'=>true,'expired_matches'=>$expired,'cleaned_intents'=>$cleaned,'time'=>date('c')]).PHP_EOL;